	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/reminder-rules", wrapper.CreateReminderRule)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/reminder-rules/{id}", wrapper.UpdateReminderRule)
